// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// Supabase: la CLI (db pull, studio, validate) debe usar la conexión directa
// (puerto 5432). Si DIRECT_URL no existe se usa DATABASE_URL.
// `prisma generate` no se conecta a la BD: sin ninguna de las dos (p. ej. en un
// clon recién descargado, al correr el postinstall) el cliente se genera igual,
// y los comandos que sí se conectan avisan que falta la URL.
const url = process.env["DIRECT_URL"] ?? process.env["DATABASE_URL"];

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  ...(url ? { datasource: { url } } : {}),
});
